input.content:
workspace "Parcel Tracker" "A C4 model of the Parcel Tracker parcel delivery tracking platform." {

    model {

        customer = person "Customer" "Looks up the status of their parcels on the Parcel Tracker."

        parcelTracker = softwareSystem "Parcel Tracker" "A parcel delivery tracking platform owned and operated by our company." {

            webPortal = container "Web Portal" "Where customers look up shipments. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Web application"

            dispatchService = container "Dispatch Service" "Assigns parcels to couriers. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Service"

            database = container "Parcel Tracker Database" "Stores shipments and dispatch records." "Database" "Database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "A third-party email delivery service operated by a different organization." "External"

        customer -> webPortal "Looks up parcel status" "HTTPS/JSON"
        webPortal -> database "Reads shipments" "SQL"
        dispatchService -> database "Stores dispatch records" "SQL"
        dispatchService -> emailProvider "Sends customer notification emails" "HTTPS/JSON"
    }

    views {
        systemContext parcelTracker "SystemContext" "System context for the Parcel Tracker." {
            include *
            autoLayout
            title "System Context for the Parcel Tracker"
        }

        container parcelTracker "Containers" "Containers of the Parcel Tracker." {
            include *
            autoLayout
            title "Containers of the Parcel Tracker"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            relationship "Relationship" {
                routing Orthogonal
            }
        }
    }

    configuration {
        scope softwaresystem
    }
}

